def b91decode(strng):
    b = 0
    n = 0
    out = []
    for c in strng:
        if c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"':
            continue
        idx = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'.index(c)
        b |= idx << n
        n += 13 if n else 7
        while n > 7:
            out.append(b & 255)
            b >>= 8
            n -= 8
    if n:
        out.append(b)
    return bytes(out)

def maxSizeSlices(self, slices: List[int]) -> int:
    n = len(slices)
    k = n // 3

    def dp(array):
        n = len(array)
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, k + 1):
                if i == 1:
                    dp[i][j] = array[0]
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i - 2][j - 1] + array[i - 1])
        return dp[n][k]

    return max(dp(slices[1:]), dp(slices[:-1]))

def numTimesAllBlue(self, light):
    count = right = 0
    for i, num in enumerate(light, 1):
        right = max(right, num)
        if right == i:
            count += 1
    return count

def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
    pair_map = {}
    for x, y in pairs:
        pair_map[x] = y
        pair_map[y] = x
    unhappy = set()
    for x in range(n):
        y = pair_map[x]
        for u in preferences[x]:
            if u == y:
                break
            v = pair_map[u]
            if preferences[u].index(x) < preferences[u].index(v):
                unhappy.add(x)
                break
    return len(unhappy)

def minSwaps(self, grid: List[List[int]]) -> int:
    n = len(grid)
    trailing_zeros = []
    for row in grid:
        zeros = 0
        for i in range(n - 1, -1, -1):
            if row[i] == 0:
                zeros += 1
            else:
                break
        trailing_zeros.append(zeros)

    swaps = 0
    for i in range(n):
        required_zeros = n - 1 - i
        found = -1
        for j in range(i, n):
            if trailing_zeros[j] >= required_zeros:
                found = j
                break
        if found == -1:
            return -1
        swaps += found - i
        row_zeros = trailing_zeros.pop(found)
        trailing_zeros.insert(i, row_zeros)
    return swaps
